import type { Knex } from 'knex';

/**
 * JGN serology catalog import. Sourced from jgn-items.xlsx
 * (sheet: 'serology'). Generated by _tmp_xlsx/build_mapping_serology.py
 * — regenerate rather than editing this file by hand.
 *
 * Renames applied to keep test_items.code unique per tenant:
 *   - CARCINOEMBRYONIC ANTIGEN (CEA)  ST018 → ST023 (dupe with β-HCG)
 *   - IONIZED CALCIUM                 CC022 → SS010 (cross-sheet collision
 *     with chemistry ALKALINE PHOSPHATASE + wrong prefix for serology)
 *   - β-HCG name: mojibake cleanup
 *
 * Result-type notes:
 *   - Almost every item is a `single`. Reference range comes from the
 *     'Normal Value' / 'REFERENCE VALUE:' row when present; lookup_values
 *     from the 'RESULT' row when the source lists semicolon-separated
 *     picks like 'Reactive;Non-Reactive'.
 *   - Salmonella typhi IgG/IgM is the one true panel (explicit IgG + IgM
 *     rows in the source).
 *   - No SI columns on this sheet, so si_* fields stay null.
 *
 * Runs via env vars:
 *   JGN_TENANT_UUID=<uuid> JGN_SERO_CATEGORY_UUID=<uuid> \
 *     npx knex seed:run --specific 09_seed_jgn_serology.ts
 *
 * Also exported as seedJgnSerology(knex, opts) for direct calls.
 * Idempotent — checks (tenant_uuid, code); components by (test_item_uuid, code).
 */

type ResultType = 'single' | 'panel';

interface ComponentSeed {
	code: string;
	name: string;
	unit_of_measure: string | null;
	reference_range: string | null;
	lookup_values: string | null;
	display_order: number;
}

