export interface SeedJgnSerologyOptions {
	tenant_uuid: string;
	item_category_uuid: string;
	created_by?: string;
}

export interface SeedJgnSerologyResult {
	items_inserted: number;
	items_skipped: number;
	components_inserted: number;
}

export async function seedJgnSerology(
	knex: Knex,
	opts: SeedJgnSerologyOptions,
): Promise<SeedJgnSerologyResult> {
	const { tenant_uuid, item_category_uuid } = opts;
	const created_by = opts.created_by ?? 'seed:09_seed_jgn_serology';
	let items_inserted = 0;
	let items_skipped = 0;
	let components_inserted = 0;

	for (const item of ITEMS) {
		let row = await knex('test_items')
			.where({ tenant_uuid, code: item.code })
			.first();
		if (row) {
			items_skipped += 1;
		} else {
			const [inserted] = await knex('test_items')
				.insert({
					tenant_uuid,
					item_category_uuid,
					code: item.code,
					name: item.name,
					result_type: item.result_type,
					method: item.method,
					unit_of_measure: item.unit_of_measure,
					reference_range: item.reference_range,
					lookup_values: item.lookup_values,
					price: item.price,
					status: 'active',
					created_by,
				})
				.returning('*');
			row = inserted;
			items_inserted += 1;
		}

		if (item.result_type === 'panel' && item.components.length) {
			for (const c of item.components) {
				const exists = await knex('test_item_components')
					.where({ test_item_uuid: row.uuid, code: c.code })
					.first();
				if (exists) continue;
				await knex('test_item_components').insert({
					tenant_uuid,
					test_item_uuid: row.uuid,
					code: c.code,
					name: c.name,
					unit_of_measure: c.unit_of_measure,
					reference_range: c.reference_range,
					lookup_values: c.lookup_values,
					display_order: c.display_order,
					created_by,
				});
				components_inserted += 1;
			}
		}
	}

	return { items_inserted, items_skipped, components_inserted };
}

export async function seed(knex: Knex): Promise<void> {
	const tenant_uuid = process.env.JGN_TENANT_UUID;
	const item_category_uuid = process.env.JGN_SERO_CATEGORY_UUID;
	if (!tenant_uuid || !item_category_uuid) {
		// eslint-disable-next-line no-console
		console.warn(
			'[seed 09] Skipped — set JGN_TENANT_UUID and JGN_SERO_CATEGORY_UUID env vars, ' +
				'or import seedJgnSerology() and call it directly with your ids.',
		);
		return;
	}
	const result = await seedJgnSerology(knex, { tenant_uuid, item_category_uuid });
	// eslint-disable-next-line no-console
	console.log(
		`[seed 09] Items inserted=${result.items_inserted} skipped=${result.items_skipped}, ` +
			`components inserted=${result.components_inserted}`,
	);
}
